insert into public.exercises (track, category, title, prompt, criteria, position) values
('deep_talk', 'Relationships', 'Ask what feeling cared for means', 'She just told you her last relationship ended because she felt unheard. Write what you say next.', array['Shows empathy before advice', 'Asks one open, gentle question', 'Avoids judging or fixing']::text[], 1),
('deep_talk', 'Relationships', 'Share your own view', 'She asks: What do you want from a relationship? Answer honestly in 3 to 5 sentences.', array['Honest and specific', 'Shows warmth without pressure', 'Invites her view back']::text[], 2),
('deep_talk', 'Dreams', 'Follow up on a dream', 'She says she secretly wants to open a bakery. Write a follow-up that deepens the topic.', array['Shows genuine curiosity', 'Asks about meaning, not just logistics', 'Encourages without overpromising']::text[], 3),
('deep_talk', 'Dreams', 'Share a dream of yours', 'Tell her about a dream you still have and why it matters, in 3 to 5 sentences.', array['Concrete detail', 'Names the emotion', 'Ends with an invitation to share']::text[], 4),
('deep_talk', 'Values', 'Explore a value', 'She says honesty matters most to her. Write what you say to explore it.', array['Reflects her words', 'Asks for a real example', 'Shares a short personal link']::text[], 5),
('deep_talk', 'Values', 'Handle a difference', 'She values saving money, you value spontaneity. Write a respectful reply that explores the difference.', array['Respectful tone', 'Curious about her reasoning', 'Looks for common ground']::text[], 6),
('deep_talk', 'Success', 'Define success', 'She asks how you define success. Answer in 3 to 5 sentences.', array['Personal and honest', 'Goes beyond money or status', 'Asks her back']::text[], 7),
('deep_talk', 'Success', 'Respond to a setback', 'She tells you she failed an important exam. Write your reply.', array['Acknowledges the feeling first', 'Offers perspective without minimizing', 'Supports instead of lecturing']::text[], 8),
('deep_talk', 'Life Vision', 'Describe your future', 'She asks where you see yourself in five years. Answer in 3 to 5 sentences.', array['Clear and specific', 'Mentions what matters, not only plans', 'Open to her vision too']::text[], 9),
('deep_talk', 'Life Vision', 'Ask about her vision', 'Write a question that invites her to describe her ideal life without sounding like an interview.', array['Warm and natural', 'Open-ended', 'Easy to answer']::text[], 10),
('deep_talk', 'Personal Growth', 'Share a lesson', 'Tell her about something you changed your mind about, in 3 to 5 sentences.', array['Honest vulnerability', 'Shows growth', 'Not preachy']::text[], 11),
('deep_talk', 'Personal Growth', 'Reflect her growth', 'She says she is proudest of learning to say no. Write your reply.', array['Reflects her feeling', 'Asks what changed', 'Celebrates without flattery']::text[], 12),
('deep_talk', 'Family', 'Ask about family gently', 'She mentions she is close to her grandmother. Write a follow-up.', array['Warm curiosity', 'Specific question', 'No pressure on painful topics']::text[], 13),
('deep_talk', 'Family', 'Respond to a hard family topic', 'She says her parents divorced when she was young. Write your reply.', array['Empathy first', 'Does not pry', 'Leaves the choice to continue with her']::text[], 14),
('deep_talk', 'Travel', 'Go beyond places', 'She says a trip to Japan changed her. Write a follow-up that goes deeper than where and when.', array['Asks what changed', 'Shows interest in feelings', 'Keeps a light tone']::text[], 15),
('deep_talk', 'Travel', 'Tell a travel story', 'Tell a short travel story that shows who you are, in 4 to 6 sentences.', array['Clear beginning, turn and end', 'Emotion or lesson', 'Leaves room for her reaction']::text[], 16),
('business', 'Networking', 'Start at an event', 'You are at an industry event next to a stranger by the coffee. Write your opener and first question.', array['Natural and low pressure', 'Curious about their work', 'Easy to answer']::text[], 17),
('business', 'Networking', 'Follow up after the event', 'Write a 3 to 5 sentence follow-up message to someone you met yesterday.', array['Specific reference to the talk', 'Clear, small ask', 'Friendly and brief']::text[], 18),
('business', 'Sales', 'Discovery questions', 'A prospect says: We are looking for a better reporting tool. Write your next two questions.', array['Open questions', 'Digs into goals and obstacles', 'No pitching yet']::text[], 19),
('business', 'Sales', 'Handle a price objection', 'A prospect says: It’s too expensive. Write your reply.', array['Acknowledges the concern', 'Asks what value they expect', 'Reframes on outcomes without pressure']::text[], 20),
('business', 'Negotiations', 'Make a first offer', 'You negotiate a contract renewal. Write how you open with your proposal.', array['Clear position', 'Gives a reason', 'Leaves room to trade']::text[], 21),
('business', 'Negotiations', 'Trade instead of concede', 'The client asks for 20 percent off. Write a reply that trades something for it.', array['Does not give in right away', 'Offers a trade such as term, volume or scope', 'Stays collaborative']::text[], 22),
('business', 'Leadership', 'Give feedback', 'A team member missed two deadlines. Write how you start the conversation.', array['Specific and factual', 'Respectful tone', 'Asks for their view']::text[], 23),
('business', 'Leadership', 'Delegate clearly', 'Write a short message that delegates a task to a colleague.', array['Clear outcome and deadline', 'Explains why it matters', 'Offers support']::text[], 24),
('business', 'Presentations', 'Open a presentation', 'Write the first 30 seconds of a talk to your leadership team about a cost problem.', array['Strong hook', 'States the main point early', 'Clear on what you need from them']::text[], 25),
('business', 'Presentations', 'Close with a call to action', 'Write the closing 20 seconds of a project proposal.', array['Summarizes in one sentence', 'One clear ask', 'Confident tone']::text[], 26),
('business', 'Meetings', 'Redirect a meeting', 'The meeting drifted off topic. Write what you say to bring it back politely.', array['Polite and firm', 'Refers to the agenda', 'Proposes a next step']::text[], 27),
('business', 'Meetings', 'Summarize decisions', 'Write a 4 sentence summary at the end of a meeting with decisions and owners.', array['Clear decisions', 'Names owners and dates', 'Brief and structured']::text[], 28),
('business', 'Client Communication', 'Deliver bad news', 'A delivery will be two weeks late. Write the message to the client.', array['Honest and early', 'Takes responsibility without excuses', 'Offers a clear plan']::text[], 29),
('business', 'Client Communication', 'Respond to a complaint', 'A client writes an angry email about a mistake. Write your reply.', array['Acknowledges the feeling', 'Takes ownership', 'Offers a concrete fix and timeline']::text[], 30)
